import assert from 'node:assert/strict';
import { applyJob } from './runner.js';

// Simple in‑memory store shared across tests
let store;

function resetStore() {
  store = {};
}

describe('applyJob', () => {
  beforeEach(() => {
    resetStore();
  });

  it('records pending then completes successfully', async () => {
    const payload = { message: 'hello' };
    await assert.doesNotThrowAsync(() => applyJob('successJob', payload, store));
    assert.strictEqual(store['successJob'], 'completed');
    // Ensure no stray pending entry
    assert.strictEqual(store['successJob'], 'completed');
  });

  it('records failure when the job throws', async () => {
    const payload = {};
    await assert.rejects(() => applyJob('failureJob', payload, store), (err) => {
      assert.match(err.message, /simulated failure/);
    });
    assert.strictEqual(store['failureJob'], 'failed');
  });

  it('splits duplicate in‑flight calls safely', async () => {
    // First call starts an inflight job
    const p = applyJob('dupJob', {}, store);
    assert.strictEqual(store['dupJob'], 'inflight');

    // Duplicate call while inflight must be a no‑op and must not throw
    await assert.doesNotThrowAsync(() => applyJob('dupJob', {}, store));
    assert.strictEqual(store['dupJob'], 'inflight');

    // Resolve the original promise to finish the job
    await p;
    assert.strictEqual(store['dupJob'], 'completed');
  });

  it('resumes after a partial failure scenario', async () => {
    // Begin a job that will eventually fail before completion
    const ongoing = applyJob('resumeTest', {}, store);
    assert.strictEqual(store['resumeTest'], 'inflight');

    // Simulate a failure during processing (catch and ignore)
    await ongoing.catch(() => {});

    // A second call with the same id should be allowed and will finish the job
    await assert.doesNotThrowAsync(() => applyJob('resumeTest', {}, store));
    assert.strictEqual(store['resumeTest'], 'completed');
  });
});
",
